import 'package:hive_flutter/hive_flutter.dart';enum AuthResult { real, decoy, failed }class DecoyService {  static const String _boxName = 'decoy_data';  static const String _decoyPasswordKey = 'decoy_password';  static const String _realPasswordKey = 'real_password';  static const String _decoyEnabledKey = 'decoy_enabled';  static const String _decoyInboxPopulatedKey = 'decoy_inbox_populated';  Box? _box;  bool _isInitialized = false;  bool get isInitialized => _isInitialized;  bool get isDecoyEnabled => _decoyEnabled;  bool _decoyEnabled = false;  Future<void> initialize() async {    if (_isInitialized) return;    _box = await Hive.openBox(_boxName);    _decoyEnabled = _box?.get(_decoyEnabledKey, defaultValue: false) ?? false;    _isInitialized = true;  }  int _simpleHash(String input) {    int hash = 0;    for (int i = 0; i < input.length; i++) {      hash = ((hash << 5) - hash) + input.codeUnitAt(i);      hash = hash & hash;    }    return hash.abs();  }  Future<void> setDecoyPassword(String password) async {    if (_box == null) await initialize();    final hashed = _simpleHash(password).toString();    await _box?.put(_decoyPasswordKey, hashed);  }  Future<void> setRealPassword(String password) async {    if (_box == null) await initialize();    final hashed = _simpleHash(password).toString();    await _box?.put(_realPasswordKey, hashed);  }  bool isDecoyPassword(String password) {    if (_box == null) return false;    final stored = _box?.get(_decoyPasswordKey);    if (stored == null) return false;    return stored.toString() == _simpleHash(password).toString();  }  bool isRealPassword(String password) {    if (_box == null) return false;    final stored = _box?.get(_realPasswordKey);    if (stored == null) return false;    return stored.toString() == _simpleHash(password).toString();  }  Future<AuthResult> authenticate(String password) async {    if (_box == null) await initialize();    if (isDecoyPassword(password)) {      return AuthResult.decoy;    }    if (isRealPassword(password)) {      return AuthResult.real;    }    return AuthResult.failed;  }  Future<void> setDecoyEnabled(bool enabled) async {    if (_box == null) await initialize();    _decoyEnabled = enabled;    await _box?.put(_decoyEnabledKey, enabled);  }  Future<void> populateDecoyInbox() async {    if (_box == null) await initialize();    final alreadyPopulated =        _box?.get(_decoyInboxPopulatedKey, defaultValue: false);    if (alreadyPopulated == true) return;    final decoyContacts = await Hive.openBox('decoy_contacts');    await decoyContacts.clear();    final decoyMessages = await Hive.openBox('decoy_messages');    await decoyMessages.clear();    final fakeContacts = [      {        'id': 'dc1',        'name': 'John Smith',        'status': 'nearby',        'lastSeen': DateTime.now().toIso8601String()      },      {        'id': 'dc2',        'name': 'Sarah Connor',        'status': 'relay',        'lastSeen':            DateTime.now().subtract(const Duration(hours: 2)).toIso8601String()      },      {        'id': 'dc3',        'name': 'Mike Johnson',        'status': 'nearby',        'lastSeen': DateTime.now()            .subtract(const Duration(minutes: 30))            .toIso8601String()      },    ];    for (final contact in fakeContacts) {      await decoyContacts.put(contact['id'], contact);    }    final fakeMessages = [      {        'id': 'dm1',        'contactId': 'dc1',        'message': 'Hey, are you available?',        'timestamp':            DateTime.now().subtract(const Duration(hours: 1)).toIso8601String(),        'isRead': true      },      {        'id': 'dm2',        'contactId': 'dc2',        'message': 'Meeting at 5pm',        'timestamp':            DateTime.now().subtract(const Duration(hours: 3)).toIso8601String(),        'isRead': false      },      {        'id': 'dm3',        'contactId': 'dc3',        'message': 'Thanks for the update',        'timestamp':            DateTime.now().subtract(const Duration(days: 1)).toIso8601String(),        'isRead': true      },    ];    for (final message in fakeMessages) {      await decoyMessages.put(message['id'], message);    }    await _box?.put(_decoyInboxPopulatedKey, true);  }}